import { ok, fail } from './result.js';
import { getCustomer, TIER_DISCOUNTS } from './customers.js';
import { getProduct } from './catalogue.js';
import { nextInvoiceNumber } from './numbering.js';
import { roundCents } from './money.js';

function isValidDate(dateString) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(dateString);
  if (!match) return false;

  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);

  // Check month and day ranges
  if (month < 1 || month > 12 || day < 1 || day > 31) return false;

  // Use Date to validate the actual date
  const date = new Date(`${dateString}T00:00:00Z`);
  return date.toISOString().startsWith(dateString);
}

function isValidDiscountPercent(discountPercent) {
  return typeof discountPercent === 'number' && discountPercent >= 0 && discountPercent <= 100;
}

/**
 * Create a new draft invoice.
 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }> }} input
 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array } } | { ok: false, error: string }}
 */
export function createInvoice({ customerId, issueDate, lines }) {
  // Validate customer exists
  const customerResult = getCustomer(customerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Validate issue date format and validity
  if (!isValidDate(issueDate)) return fail('DATE_INVALID');

  // Validate lines is not empty
  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');

  // Validate and enrich each line
  const enrichedLines = [];
  for (const line of lines) {
    // Validate qty
    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');

    // Determine discountPercent: use provided value if explicit, else use tier discount
    let discountPercent;
    if (line.discountPercent !== undefined) {
      discountPercent = line.discountPercent;
    } else {
      discountPercent = TIER_DISCOUNTS[customer.tier];
    }

    if (!isValidDiscountPercent(discountPercent)) return fail('DISCOUNT_INVALID');

    // Get product info
    const productResult = getProduct(line.sku);
    if (!productResult.ok) return productResult;

    const product = productResult.value;
    enrichedLines.push({
      sku: line.sku,
      name: product.name,
      qty: line.qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent,
    });
  }

  return ok({
    customerId,
    issueDate,
    status: 'draft',
    lines: enrichedLines,
  });
}

/**
 * Calculate the total for a single line item (before discount).
 * @param {{ qty: number, unitPrice: number }} line
 * @returns {number} Total in cents
 */
export function lineTotal(line) {
  return line.qty * line.unitPrice;
}

/**
 * Calculate the discount amount for a single line item.
 * @param {{ qty: number, unitPrice: number, discountPercent?: number }} line
 * @returns {number} Discount in cents
 */
export function lineDiscount(line) {
  const discountPercent = line.discountPercent ?? 0;
  const total = lineTotal(line);
  const discount = roundCents((total * discountPercent) / 100);
  return Math.max(0, discount);
}

/**
 * Calculate the VAT amount for a single line item (after discount).
 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }} line
 * @returns {number} VAT in cents
 */
export function lineVat(line) {
  const total = lineTotal(line);
  const discount = lineDiscount(line);
  const amountAfterDiscount = total - discount;
  const vat = roundCents((amountAfterDiscount * line.vatRate) / 100);
  return Math.max(0, vat);
}

/**
 * Calculate totals for an invoice.
 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }> }} invoice
 * @returns {{ subtotal: number, discount: number, vat: number, total: number }} Totals in cents
 */
export function invoiceTotals(invoice) {
  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
  const vat = invoice.lines.reduce((sum, line) => sum + lineVat(line), 0);
  const total = Math.max(0, subtotal - discount + vat);
  return {
    subtotal,
    discount,
    vat,
    total,
  };
}

/**
 * Add or update a line on a draft invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {{ sku: string, qty: number, discountPercent?: number }} input
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function addLine(invoice, { sku, qty, discountPercent }) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Validate qty
  if (!Number.isInteger(qty) || qty <= 0) return fail('QTY_INVALID');

  // Get customer for tier discount
  const customerResult = getCustomer(invoice.customerId);
  if (!customerResult.ok) return customerResult;
  const customer = customerResult.value;

  // Determine discountPercent: use provided value if explicit, else use tier discount
  let finalDiscountPercent;
  if (discountPercent !== undefined) {
    finalDiscountPercent = discountPercent;
  } else {
    finalDiscountPercent = TIER_DISCOUNTS[customer.tier];
  }

  if (!isValidDiscountPercent(finalDiscountPercent)) return fail('DISCOUNT_INVALID');

  // Get product info
  const productResult = getProduct(sku);
  if (!productResult.ok) return productResult;

  const product = productResult.value;

  // Check if SKU already exists on invoice
  const existingLineIndex = invoice.lines.findIndex((line) => line.sku === sku);

  // Create new lines array
  const newLines = invoice.lines.map((line) => ({ ...line }));

  if (existingLineIndex >= 0) {
    // Update existing line
    newLines[existingLineIndex] = {
      ...newLines[existingLineIndex],
      qty: newLines[existingLineIndex].qty + qty,
    };
  } else {
    // Add new line
    newLines.push({
      sku,
      name: product.name,
      qty,
      unitPrice: product.unitPrice,
      vatRate: product.vatRate,
      discountPercent: finalDiscountPercent,
    });
  }

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Remove a line from a draft invoice.
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {string} sku
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function removeLine(invoice, sku) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Check if SKU exists
  const lineIndex = invoice.lines.findIndex((line) => line.sku === sku);
  if (lineIndex < 0) return fail('LINE_NOT_FOUND');

  // Check if this is the last line
  if (invoice.lines.length === 1) return fail('NO_LINES');

  // Create new lines array without the removed line
  const newLines = invoice.lines.filter((line) => line.sku !== sku);

  return ok({
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: invoice.status,
    lines: newLines,
  });
}

/**
 * Issue a draft invoice (assign a number and mark as issued).
 * @param {{ status: string, customerId: string, issueDate: string, lines: Array }} invoice
 * @param {string[]} existingNumbers - Invoice numbers already issued
 * @returns {{ ok: true, value: object } | { ok: false, error: string }}
 */
export function issueInvoice(invoice, existingNumbers) {
  // Check invoice is draft
  if (invoice.status !== 'draft') return fail('NOT_DRAFT');

  // Get next invoice number
  const number = nextInvoiceNumber(existingNumbers, invoice.issueDate);

  return ok({
    number,
    customerId: invoice.customerId,
    issueDate: invoice.issueDate,
    status: 'issued',
    lines: invoice.lines.map((line) => ({ ...line })),
  });
}

